/// Raw Ed25519 public key length. Keys travel as standard-base64 of these bytes,
/// matching the encoding the license registry uses for its `public_keys` map.
pub const PUBLIC_KEY_BYTES: usize = 32;

/// Envelope format version. Bumped only for a breaking change to the wrapper
/// itself, never for a change to the claims inside either token.
pub const ENVELOPE_VERSION: u32 = 1;

/// Upper bound on an encoded license key. Two JWTs and a small wrapper are well
/// under this; the cap exists so a hostile input cannot force a large allocation
/// before any signature has been checked.
pub const MAX_ENVELOPE_BYTES: usize = 32 * 1024;

/// Claim-set version for the attestation itself.
pub const ATTESTATION_VERSION: u32 = 1;

/// Fixed issuer and audience. Platform-wide constants rather than per-product
/// configuration, so a token minted for some other purpose can never be replayed
/// as a signing delegation.
pub const ATTESTATION_ISSUER: &str = "untra-root";
pub const ATTESTATION_AUDIENCE: &str = "untra-trust";

/// The only purpose this code will honour. A future purpose (say, telemetry
/// signing) must not be accepted as authority to sign licenses.
pub const PURPOSE_LICENSE_SIGNING: &str = "license-signing";

